begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(16);
select has_table('public','backup_policies','backup policy persistence');
select has_table('public','backup_runs','two-kind durable runs');
select has_function('public','m15_05_backup_control',array['uuid','text','text','jsonb'],'narrow control surface');
select has_function('public','m15_05_backup_assurance',array['uuid','uuid','integer','uuid','text'],'org scoped assurance');
select ok(exists(select 1 from pg_roles where rolname='cra_backup_control' and not rolbypassrls and not rolsuper),'control role does not bypass RLS');
select ok(not has_table_privilege('authenticated','public.backup_runs','SELECT'),'browser table access denied');
select ok(not has_function_privilege('service_role','public.m15_05_backup_control(uuid,text,text,jsonb)','EXECUTE'),'service role cannot execute backups');
select ok(not has_function_privilege('cra_operator_registry_reader','public.m15_05_backup_control(uuid,text,text,jsonb)','EXECUTE'),'metadata grants do not execute backups');
select ok((select bool_and(relrowsecurity and not relforcerowsecurity) from pg_class where oid in ('public.backup_runs'::regclass,'public.backup_policies'::regclass)),'non-forced RLS');
select ok((select count(*)=2 from pg_class where relname in ('backup_policies','backup_runs') and relnamespace='public'::regnamespace),'exactly two feature tables');
select is(public.m15_05_backup_control('00000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000001','run/read','{"runId":"00000000-0000-4000-8000-000000000002"}')->>'outcome','not_found','missing instances do not disclose runs');
select is((public.m15_05_backup_control('00000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000001','policy/validate','{"configuration":{"sourceAlias":"local-source","repositoryAlias":"off-host","stagingAlias":"private-ram","keyAlias":"backup-key-v1","targetProfile":"isolated-saas","residency":"local","schedulingEnabled":false,"checkpointIntervalMinutes":30,"baseIntervalHours":24,"verificationIntervalDays":30,"retentionDays":30,"pauseLimitSeconds":120}}')->'result'->>'valid'),'false','syntactic policy validation cannot claim native proof');
select is((public.m15_05_backup_control('00000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000001','policy/validate','{"configuration":{"sourceAlias":"../secret"}}')->'result'->>'valid'),'false','policy validation rejects unsafe envelopes without a transport parse failure');
select is(public.m15_05_backup_control('00000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000001','run/list','{}')->'result','{"items":[],"nextCursor":null}'::jsonb,'empty deployment history is an empty collection');
select throws_ok($$select public.m15_05_backup_control('00000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000001','unsafe','{}')$$,'22023',null,'unknown operations rejected');
select ok((select rolconfig @> array['statement_timeout=500ms'] from pg_roles where rolname='cra_operator_registry_reader'),'metadata role has an actual pre-statement deadline');
select * from finish();
rollback;
